// Footer sections and GitHub body-size handling.

const GITHUB_BODY_MAX = 65536;

function mergeOrderSection() {
  return `## Recommended Merge Order\n\n` +
    `- Validate updates before merging.\n` +
    `- Merge non-breaking updates first.\n` +
    `- Review breaking changes.\n` +
    `- Re-run this workflow after each merge.\n\n`;
}

function footerSection(runUrl) {
  return `---\n_Generated by [Security Vulnerability Remediation](${runUrl})_`;
}

function truncateForGitHub(body, runUrl) {
  if (body.length <= GITHUB_BODY_MAX) return body;
  const notice = `\n\n---\n> ⚠️ **Content truncated**: this tracking issue exceeded GitHub's ${GITHUB_BODY_MAX}-character body limit. ` +
    `See the full details in the [workflow run](${runUrl}) artifacts.\n`;
  return body.slice(0, GITHUB_BODY_MAX - notice.length) + notice;
}

module.exports = { mergeOrderSection, footerSection, truncateForGitHub };
